def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    valid = rem >= 0
    if not np.any(valid):
        return np.full_like(bins, -np.inf, dtype=float)
    original_capacities = bins
    filled_ratio = (original_capacities - rem) / original_capacities
    target_ratio = 0.85
    score = -np.abs(filled_ratio - target_ratio)
    return np.where(valid, score, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    valid = rem >= 0
    if not np.any(valid):
        return np.full_like(bins, -np.inf, dtype=float)
    valid_rem = np.where(valid, rem, -np.inf)
    max_rem = np.max(valid_rem)
    min_rem = np.min(np.where(valid, rem, np.inf))
    target_rem = 0.75 * min_rem + 0.25 * max_rem
    return np.where(valid, -abs(rem - target_rem), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    valid = rem >= 0
    if not np.any(valid):
        return np.full_like(bins, -np.inf, dtype=float)
    valid_rem = np.where(valid, rem, -np.inf)
    max_rem = np.max(valid_rem)
    almost_max_rem = np.max(np.where(valid_rem < max_rem, valid_rem, -np.inf))
    target_rem = almost_max_rem if almost_max_rem != -np.inf else max_rem
    return np.where(rem == target_rem, 0.0, np.where(valid, -abs(rem - target_rem), -np.inf))
